-- See https://wiki.hyprland.org/Configuring/Window-Rules/ for more
-- Hyprland 0.53+ syntax
-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

hl.window_rule({
    match = {
        class = ".*",
    },
    suppress_event = "maximize",
})

-- Just dash of opacity by default
hl.window_rule({
    match = {
        class = ".*",
    },
    opacity = "0.97 0.9",
})

-- Fix some dragging issues with XWayland
hl.window_rule({
    match = {
        class = "^$",
        title = "^$",
        xwayland = 1,
        float = 1,
        fullscreen = 0,
        pin = 0,
    },
    no_focus = true,
})

-- App-specific tweaks
-- Source: ~/.config/rice/defaults/hypr/apps.conf — convert this file to Lua and ensure it is on Lua's package.path.
require(os.getenv("HOME") .. "/.config/rice/defaults/hypr/apps")
